import dynamic from "next/dynamic";
import { MOCK_PARKING_SPACES } from "@/lib/mock-parking-spaces";

const ZagrebMap = dynamic(
  () => import("./ZagrebMap").then((mod) => mod.ZagrebMap),
  {
    ssr: false,
    loading: () => (
      <div
        className="flex h-[min(56vh,420px)] min-h-[240px] w-full items-center justify-center rounded-2xl border border-zinc-200 bg-zinc-100/80 text-sm text-zinc-500 dark:border-zinc-800 dark:bg-zinc-900/50 dark:text-zinc-400 sm:h-[min(50vh,480px)] sm:min-h-[280px]"
        role="status"
        aria-live="polite"
      >
        Učitavanje karte Zagreba…
      </div>
    ),
  }
);

export function MapPlaceholder() {
  return (
    <section id="map" className="scroll-mt-20 border-y border-zinc-200/80 bg-zinc-50/30 px-4 py-12 dark:border-zinc-800/80 dark:bg-zinc-950/20 sm:px-6">
      <div className="mx-auto max-w-6xl">
        <div className="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <h2 className="text-xl font-semibold tracking-tight text-foreground">Karta Zagreba</h2>
            <p className="mt-1 text-sm text-zinc-600 dark:text-zinc-400">
              OpenStreetMap — označena su demo parkirališta u gradu.
            </p>
          </div>
        </div>
        <div className="mt-6 overflow-hidden rounded-2xl border border-zinc-200 shadow-sm ring-1 ring-zinc-200/60 dark:border-zinc-800 dark:ring-zinc-800/80">
          <ZagrebMap locations={MOCK_PARKING_SPACES} />
        </div>
      </div>
    </section>
  );
}
